#!/usr/bin/env node
// dsh-tavern-sqlite-v2 · 「存档格式」桥施缝（作者客户端 UI 接缝）
//
// 只写作者树的两个客户端文件，不打开会话、不改数据、不重启服务：
//   源码：新拆分树features/play-controls.js；旧内联树main.js（按include精确选择）
//   tavern-plugin/lib/client.js        构建产物（首行 `// Generated by pnpm build:client`）
// 作者构建脚本 `bin/build-tavern-client.mjs` 只做「// @include 内联 + 追加 CSS」，正文逐字保留
// ⇒ 源码与产物**同构**，同一 transform 对两个文件都成立（必须同施/同卸，状态不一致时响亮拒绝）。
//
// ── 宿主侧契约（由我们的 client 模块实现；本文件只做作者树接缝，不实现也不需要它） ──
//   service 名： 'tavernStorageUi'
//   value 形状：
//     { active: true,
//       renderSavePanel(props) { return React.createElement(MigrationPanel, { ...props, key: props.sessionId }) } }
//   自有 ephemeral 事件（非 Session 事件）： 'tavern-storage-ui/change'
//   卸载顺序（必须）：先 `ui.active = false`，**再** `ctx.emit('tavern-storage-ui/change')`
//     —— 服务在 fiber 卸载完成前仍可能被 ctx.get 读到，所以桥**每 render** 都读一次并检查
//        `active === true`；事件只负责触发重渲染，不承担"服务已移除"的判定。
//   本文件不使用 cordis `internal/*` 内部事件（不依赖未公开契约）。
//
// ── 两个接缝（transformSaveUiClient） ──
//   ① 作者「酒馆状态」正常状态体里插入桥：
//        h(TavernStorageSaveBridge, { ctx: props.storageUiCtx, sessionId: props.sessionId }),
//      · 变体甲（作者已有迁移区；2026-09-30 洁净实例真身 `blank-clean-client-0930.js`：状态体 =
//        TavernBackgroundWait → h(TavernStorageMigration, …) → 重载人物卡 section）
//        ⇒ 紧邻作者迁移区**之后**（`h(TavernStorageMigration, …)` 那行后面），不接管作者区块；
//      · 变体乙（更早版本无迁移区；离线基线真身即此形）⇒ 正常状态体**最前**（TavernBackgroundWait 之前）；
//      · 两种变体各自要求结构证据（锚点上一行必须与前项吻合），否则 fail closed。
//   ② 桥函数定义（内联在 TavernStatusTab 之前）+ 两处 ctx 转发：
//        status tab 注册处 `storageUiCtx: ctx` → TavernStatusTab → TavernStatusPanel `storageUiCtx: props.storageUiCtx`
//   不接管作者原有「迁移旧存档」区块：不读、不删、不替换它的任何代码，只做插入。
//
// ── fail-closed 纪律 ──
//   · 每个锚点必须**唯一命中**，0 或 >1 一律抛错（多版本严格唯一锚点）；
//   · 变体甲：迁移区那行的上一行必须是状态体里的 TavernBackgroundWait；
//     变体乙：TavernBackgroundWait 那行的上一行必须就是状态体开头；
//   · 两种结构证据都不成立（作者又改版）⇒ 抛错，不猜、不编造锚点。
//
// 用法（在酒馆主机上跑；`node` ≥22）：
//   node <包目录>/deploy/apply-save-ui-seam.mjs              # 施缝（幂等；已是最新只报告）
//   node <包目录>/deploy/apply-save-ui-seam.mjs --check      # 只检查不改（退出码 0=已就绪 / 3=需施缝）
//   node <包目录>/deploy/apply-save-ui-seam.mjs --uninstall  # 卸缝（按本缝独立 manifest 精确还原）
//   node <包目录>/deploy/apply-save-ui-seam.mjs --app <目录> # 指定酒馆应用树（默认自动定位）
//
// ── 生效范围与措辞纪律（不外推） ──
//   本文件只改**作者客户端**两个文件：改完由浏览器重新加载客户端资源即可看到（不是服务端接缝）。
//   **不承诺**「无需重启」这类全局结论：本轮 host 侧存档协议另有 auth / 维护步骤，须按其自身流程核。
//
// ── 现状与前置核对（2026-09-30） ──
//   本地只有**当前版本的构建产物**快照（`.tmp-verify-clean-install/blank-clean-client-0930.js`，
//   首行 `// Generated by pnpm build:client`）；**同一版本的 src/client/main.js 未知**。
//   ⇒ 现场必须先对两个文件 `--check`（只读）确认锚点各自唯一命中，再 apply；
//     若两文件版本错位（只有一个脏）会以「两文件接缝状态不一致」响亮拒绝，不要绕过。
import { existsSync, readFileSync, writeFileSync, copyFileSync, unlinkSync } from 'node:fs'
import { fileURLToPath, pathToFileURL } from 'node:url'
import os from 'node:os'
import path from 'node:path'
import vm from 'node:vm'

export const SAVE_UI_MARKER = '// [dsh-tavern-save-ui-seam:v1]'
export const SAVE_UI_SERVICE = 'tavernStorageUi'
export const SAVE_UI_EVENT = 'tavern-storage-ui/change'
export const SAVE_UI_BRIDGE = 'TavernStorageSaveBridge'
/** 施缝目标：源码与构建产物（同构 ⇒ 同一 transform）。 */
export const SAVE_UI_TARGETS = Object.freeze([
  'tavern-plugin/src/client/main.js',
  'tavern-plugin/lib/client.js'
])
export function saveUiTargets(appDir){
  const main='tavern-plugin/src/client/main.js',feature='tavern-plugin/src/client/features/play-controls.js'
  if(existsSync(path.join(appDir,main)) && readFileSync(path.join(appDir,main),'utf8').includes('// @include features/play-controls.js'))return [feature,'tavern-plugin/lib/client.js']
  return [...SAVE_UI_TARGETS]
}
export const SAVE_UI_MANIFEST = '.tavern-save-ui-seam.json'

// ── 锚点（作者客户端正文；源码与产物逐字相同） ──
const BODY_OPEN = 'h("div", { className: "dsh-tavern-status-body" },'
const BODY_FIRST = 'h(TavernBackgroundWait, {sessionId:props.sessionId, activity:view.activity}),'
const MIGRATION_CALL = 'h(TavernStorageMigration, '
const STATUS_TAB_FN = 'function TavernStatusTab(props) {'
const STATUS_TAB_VIEW = 'return h(TavernStatusPanel, { sessionId: props.sessionId,'
const STATUS_TAB_REGISTER = 'React.createElement(TavernStatusTab, { sessions: ctx.sessions,'

const BRIDGE_CALL = `h(${SAVE_UI_BRIDGE}, { ctx: props.storageUiCtx, sessionId: props.sessionId }),`
const BRIDGE_VIEW_NEXT = 'return h(TavernStatusPanel, { storageUiCtx: props.storageUiCtx, sessionId: props.sessionId,'
const BRIDGE_REGISTER_NEXT = `React.createElement(TavernStatusTab, { storageUiCtx: ctx, sessions: ctx.sessions,`

/** 桥函数定义（相对缩进；插入时按 TavernStatusTab 的实际缩进补齐）。 */
function bridgeDefinitionLines() {
  return [
    SAVE_UI_MARKER,
    '// 作者面板里的纯 React 桥：只读我们的可选服务；每 render 读一次，active !== true 一律不渲染。',
    `function ${SAVE_UI_BRIDGE}(props) {`,
    '\tconst ctx = props.ctx;',
    '\tconst read = function () {',
    `\t\tconst ui = ctx && typeof ctx.get === "function" ? ctx.get(${JSON.stringify(SAVE_UI_SERVICE)}) : undefined;`,
    '\t\treturn ui && ui.active === true && typeof ui.renderSavePanel === "function" ? ui : undefined;',
    '\t};',
    '\tconst [, bump] = React.useState(0);',
    '\tReact.useEffect(function () {',
    '\t\tif (!ctx || typeof ctx.on !== "function") return function () {};',
    '\t\tconst refresh = function () { bump(function (value) { return value + 1; }); };',
    `\t\tconst dispose = ctx.on(${JSON.stringify(SAVE_UI_EVENT)}, refresh); // 先订阅，避免 mount 间隙漏事件`,
    '\t\trefresh();',
    '\t\treturn function () { if (typeof dispose === "function") dispose(); };',
    '\t}, [ctx]);',
    '\tconst ui = read();',
    '\tif (ui === undefined) return null;',
    '\treturn ui.renderSavePanel({ sessionId: props.sessionId });',
    '}',
    ''
  ]
}

function countOf(source, needle) {
  let count = 0
  let index = 0
  while ((index = source.indexOf(needle, index)) >= 0) { count += 1; index += needle.length }
  return count
}

function requireUnique(source, needle, label) {
  const count = countOf(source, needle)
  if (count !== 1) {
    throw new Error(`存档格式桥接缝锚点${count === 0 ? '缺失' : '不唯一'}（${label}，命中 ${count}）——作者客户端布局未知，拒绝猜测`)
  }
  return source.indexOf(needle)
}

function lineStartOf(source, index) {
  const newline = source.lastIndexOf('\n', index - 1)
  return newline + 1
}

function indentOf(source, lineStart) {
  const matched = /^[ \t]*/.exec(source.slice(lineStart, lineStart + 128))
  return matched === null ? '' : matched[0]
}

function replaceOnce(source, needle, next, label) {
  const at = requireUnique(source, needle, label)
  return source.slice(0, at) + next + source.slice(at + needle.length)
}

/** 把整段行插到某锚点所在行的前面，缩进取该锚点行的实际缩进。 */
function insertLinesBefore(source, needle, lines, label) {
  const at = requireUnique(source, needle, label)
  const lineStart = lineStartOf(source, at)
  const indent = indentOf(source, lineStart)
  const block = lines.map(line => (line === '' ? '' : indent + line)).join('\n') + '\n'
  return source.slice(0, lineStart) + block + source.slice(lineStart)
}

function lineEndOf(source, index) {
  const newline = source.indexOf('\n', index)
  return newline < 0 ? source.length : newline
}

/** 读锚点所在行的「上一行」去空白文本（用于结构证据）；无上一行时返回 undefined。 */
function previousLineOf(source, lineStart) {
  if (lineStart === 0) return undefined
  return source.slice(lineStartOf(source, lineStart - 1), lineStart - 1).trim()
}

/** 接缝①变体甲：紧邻作者迁移区之后插入（不接管作者的区块）。 */
function insertAfterMigration(source) {
  const at = requireUnique(source, MIGRATION_CALL, '作者迁移区 h(TavernStorageMigration, …)')
  const lineStart = lineStartOf(source, at)
  if (previousLineOf(source, lineStart) !== BODY_FIRST) {
    throw new Error('存档格式桥接缝：作者迁移区上一行不是 TavernBackgroundWait——未知布局 fail closed，'
      + '待现场 anchor 再支持，不编造锚点')
  }
  const indent = indentOf(source, lineStart)
  const lineEnd = lineEndOf(source, at)
  return source.slice(0, lineEnd + 1) + indent + BRIDGE_CALL + '\n' + source.slice(lineEnd + 1)
}

/** 接缝①变体乙：正常状态体最前（TavernBackgroundWait 之前）插入。 */
function insertAtBodyFront(source) {
  const at = requireUnique(source, BODY_FIRST, '状态体首子节点 TavernBackgroundWait')
  const lineStart = lineStartOf(source, at)
  if (lineStart === 0) throw new Error('存档格式桥接缝：状态体首子节点不在独立行，布局未知，拒绝猜测')
  if (previousLineOf(source, lineStart) !== BODY_OPEN) {
    throw new Error('存档格式桥接缝：正常状态体首子节点既不是作者迁移区、上一行也不是状态体开头'
      + '（作者可能已改版）——未知布局 fail closed，待现场 anchor 再支持，不编造锚点')
  }
  const indent = indentOf(source, lineStart)
  return source.slice(0, lineStart) + indent + BRIDGE_CALL + '\n' + source.slice(lineStart)
}

/**
 * 接缝①：正常状态体里插入桥。
 *   变体甲 = 作者已有迁移区（当前真身）⇒ 紧邻迁移区之后；
 *   变体乙 = 无迁移区（更早真身）⇒ 状态体最前；
 *   迁移区锚点 >1 命中或结构证据不成立 ⇒ fail closed。
 */
function insertBridgeCall(source) {
  const migrationHits = countOf(source, MIGRATION_CALL)
  if (migrationHits > 1) {
    throw new Error(`存档格式桥接缝锚点不唯一（作者迁移区 h(TavernStorageMigration, …)，命中 ${migrationHits}）——拒绝猜测`)
  }
  return migrationHits === 1 ? insertAfterMigration(source) : insertAtBodyFront(source)
}

/**
 * 作者客户端源码 → 施缝后的源码（纯函数；两个接缝）。
 * 幂等：已含标记时校验完整性后原样返回；部分施缝/同名函数已存在时响亮拒绝。
 */
export function transformSaveUiClient(source) {
  if (typeof source !== 'string' || source === '') throw new Error('transformSaveUiClient：缺少作者客户端源码文本')
  if (source.includes(SAVE_UI_MARKER)) {
    for (const required of [SAVE_UI_BRIDGE, BRIDGE_CALL, `ctx.get(${JSON.stringify(SAVE_UI_SERVICE)})`,
      `ctx.on(${JSON.stringify(SAVE_UI_EVENT)}`, 'storageUiCtx: ctx', 'storageUiCtx: props.storageUiCtx']) {
      if (!source.includes(required)) throw new Error('存档格式桥接缝标记存在但实现不完整（缺少 ' + required + '），拒绝猜测修复')
    }
    return source
  }
  if (source.includes(SAVE_UI_BRIDGE)) {
    throw new Error('作者客户端已存在 ' + SAVE_UI_BRIDGE + '（可能被其它工具改过），拒绝覆盖')
  }
  let out = insertBridgeCall(source)
  out = insertLinesBefore(out, STATUS_TAB_FN, bridgeDefinitionLines(), 'TavernStatusTab 定义')
  out = replaceOnce(out, STATUS_TAB_VIEW, BRIDGE_VIEW_NEXT, 'TavernStatusPanel props 转发')
  out = replaceOnce(out, STATUS_TAB_REGISTER, BRIDGE_REGISTER_NEXT, 'status tab 注册 ctx 转发')
  if (!out.includes(SAVE_UI_MARKER) || !out.includes(BRIDGE_CALL)) throw new Error('存档格式桥接缝未生效，拒绝写入')
  return out
}

/** 默认解析校验：与作者构建脚本同款（`new vm.Script`），只编译不执行、不写盘。 */
export function defaultSyntaxCheck(code, file) {
  return new vm.Script(code, { filename: file })
}

/** 精确路径越界守卫：写入/删除前一律先确认目标在应用树内。 */
function assertInside(root, target) {
  const resolved = path.resolve(target)
  const base = path.resolve(root)
  if (resolved === base || resolved.startsWith(base + path.sep)) return resolved
  throw new Error('路径越界，拒绝操作：' + resolved)
}

function readManifest(manifestPath) {
  if (!existsSync(manifestPath)) return undefined
  const parsed = JSON.parse(readFileSync(manifestPath, 'utf8'))
  return Array.isArray(parsed?.entries) ? parsed.entries : []
}

/**
 * 卸载只依据本缝自己的 manifest：
 *   · 有 manifest ⇒ 按 entries 精确还原并删自己的备份；
 *   · **无 manifest 但目标文件仍含接缝标记** ⇒ 抛错（缺少施缝记录，拒绝猜测还原）；标准入口因此能在
 *     动 legacy/main 之前失败，不会留下「UI 还在、别的缝已卸」的假成功；
 *   · 无 manifest 且无标记 ⇒ 安全幂等跳过（未施过的树）。
 */
function uninstallSaveUiSeam({ appDir, manifestPath, check }) {
  if (!existsSync(manifestPath)) {
    const marked = SAVE_UI_TARGETS.filter(relative => {
      const file = assertInside(appDir, path.join(appDir, relative))
      return existsSync(file) && readFileSync(file, 'utf8').includes(SAVE_UI_MARKER)
    })
    if (marked.length > 0) {
      throw new Error('缺少存档格式桥接缝记录（' + SAVE_UI_MANIFEST + '），但目标文件仍含接缝标记：'
        + marked.join('、') + '——拒绝猜测还原（请人工核对该树或用首次备份恢复）')
    }
    return { changed: false, removed: false }
  }
  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'))
  const entries = Array.isArray(manifest?.entries) ? manifest.entries : []
  for (const entry of entries) {
    if (!existsSync(assertInside(appDir, path.join(appDir, entry.backup)))) {
      throw new Error('缺少存档格式桥接缝备份：' + entry.relative)
    }
  }
  if (check) return { changed: false, removed: false, needsUninstall: true }
  for (const entry of entries) {
    copyFileSync(assertInside(appDir, path.join(appDir, entry.backup)), assertInside(appDir, path.join(appDir, entry.relative)))
  }
  for (const entry of entries) unlinkSync(assertInside(appDir, path.join(appDir, entry.backup)))
  unlinkSync(assertInside(appDir, manifestPath))
  return { changed: true, removed: true }
}

/**
 * 施缝 / 卸缝。写盘前**先**对两个文件的 transform 结果做解析预验证；任一步失败整体回滚（含备份与 manifest）。
 * @param appDir - 作者应用树绝对路径
 * @param check - 只检查不改
 * @param uninstall - 按本缝独立 manifest 精确还原
 * @param syntaxCheck - 注入解析校验（测试用；默认 defaultSyntaxCheck）
 */
export function applySaveUiSeam({ appDir, check = false, uninstall = false, syntaxCheck } = {}) {
  if (!appDir || !path.isAbsolute(appDir)) throw new Error('必须明确指定作者应用树绝对路径')
  const manifestPath = path.join(appDir, SAVE_UI_MANIFEST)
  if (uninstall) return uninstallSaveUiSeam({ appDir, manifestPath, check })
  const validate = syntaxCheck || defaultSyntaxCheck
  const changes = saveUiTargets(appDir).map(relative => {
    const file = path.join(appDir, relative)
    if (!existsSync(file)) throw new Error('缺少作者客户端文件：' + relative)
    const before = readFileSync(file, 'utf8')
    const after = transformSaveUiClient(before)
    return { relative, file, before, after, dirty: before !== after }
  })
  // 预验证：两个文件都先解析一次，全部通过才允许写盘。
  for (const change of changes) validate(change.after, change.file)
  const dirty = changes.filter(change => change.dirty)
  if (dirty.length === 1) {
    throw new Error('作者客户端两文件接缝状态不一致（源码与产物必须同构）：' + dirty.map(change => change.relative).join('、'))
  }
  if (!dirty.length || check) return { changed: false, needsApply: dirty.length > 0, files: dirty.map(change => change.relative) }
  const previousManifest = existsSync(manifestPath) ? readFileSync(manifestPath, 'utf8') : undefined
  const recorded = readManifest(manifestPath) || []
  const newBackups = []
  // 本次操作的**内存前像**：只服务「同一次操作的回退」，不代替卸载用的首次原像与已定义 backup 文件。
  const snapshot = {
    files: dirty.map(change => ({ relative: change.relative, before: change.before })),
    manifest: previousManifest,
    createdBackups: []
  }
  try {
    for (const change of dirty) {
      if (!recorded.some(entry => entry.relative === change.relative)) {
        const backup = change.relative + '.save-ui-seam.backup'
        const backupPath = assertInside(appDir, path.join(appDir, backup))
        if (existsSync(backupPath)) throw new Error('未知旧备份存在，拒绝覆盖：' + backup)
        copyFileSync(change.file, backupPath)
        newBackups.push(backupPath)
        snapshot.createdBackups.push(backup)
        recorded.push({ relative: change.relative, backup })
      }
      writeFileSync(change.file, change.after, 'utf8')
    }
    // 回读复核（库/文件内通过 ≠ 生效；这里至少证明落盘字节可解析且含接缝）。
    for (const change of dirty) {
      const written = readFileSync(change.file, 'utf8')
      validate(written, change.file)
      if (!written.includes(SAVE_UI_MARKER)) throw new Error('回读复核失败：接缝未落盘（' + change.relative + '）')
    }
    writeFileSync(manifestPath, JSON.stringify({ version: 1, marker: SAVE_UI_MARKER, service: SAVE_UI_SERVICE, event: SAVE_UI_EVENT, entries: recorded }, null, 2) + '\n', 'utf8')
  } catch (error) {
    for (const change of dirty) writeFileSync(change.file, change.before, 'utf8')
    for (const file of newBackups) if (existsSync(file)) unlinkSync(file)
    if (previousManifest === undefined) { if (existsSync(manifestPath)) unlinkSync(manifestPath) }
    else writeFileSync(manifestPath, previousManifest, 'utf8')
    throw error
  }
  return { changed: true, needsApply: false, files: dirty.map(change => change.relative), snapshot }
}

/**
 * 用**同一次 apply 返回的内存前像**精确回退（供上层「host 失败」联动回退用）。
 * 只回写本次改过的两个文件、恢复本次的 manifest 前像、删掉本次新建的精确备份路径；
 * 不动长期备份、不动其它缝的 manifest；每个删除目标都先做应用树内路径核对。
 */
export function restoreSaveUiSnapshot({ appDir, snapshot }) {
  if (!appDir || !path.isAbsolute(appDir)) throw new Error('必须明确指定作者应用树绝对路径')
  if (!snapshot || !Array.isArray(snapshot.files)) throw new Error('缺少本次操作的内存前像，拒绝回退')
  for (const file of snapshot.files) {
    if (typeof file?.relative !== 'string' || typeof file?.before !== 'string') throw new Error('内存前像不完整，拒绝回退')
    writeFileSync(assertInside(appDir, path.join(appDir, file.relative)), file.before, 'utf8')
  }
  const manifestPath = assertInside(appDir, path.join(appDir, SAVE_UI_MANIFEST))
  if (snapshot.manifest === undefined) { if (existsSync(manifestPath)) unlinkSync(manifestPath) }
  else writeFileSync(manifestPath, snapshot.manifest, 'utf8')
  for (const relative of snapshot.createdBackups || []) {
    const backupPath = assertInside(appDir, path.join(appDir, relative))
    if (existsSync(backupPath)) unlinkSync(backupPath)
  }
  return { restored: true }
}

function defaultAppDir() {
  const home = process.env.DSH_HOME || path.join(os.homedir(), '.dsh-tavern')
  const profile = path.join(home, 'profiles', 'tavern', 'package.json')
  if (existsSync(profile)) {
    const declared = JSON.parse(readFileSync(profile, 'utf8'))?.dshTavern?.source
    if (typeof declared === 'string' && declared) return path.resolve(declared)
  }
  return path.join(home, 'apps', 'dsh-tavern')
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  try {
    const args = process.argv.slice(2)
    const position = args.indexOf('--app')
    if (position >= 0 && (!args[position + 1] || args[position + 1].startsWith('--'))) throw new Error('--app 缺少应用树路径')
    const appDir = position >= 0 ? path.resolve(args[position + 1]) : defaultAppDir()
    const result = applySaveUiSeam({ appDir, check: args.includes('--check'), uninstall: args.includes('--uninstall') })
    console.log(result.changed
      ? (result.removed ? '存档格式桥接缝已卸除；浏览器硬刷新即可。' : '存档格式桥接缝已更新；浏览器硬刷新即可。')
      : result.needsUninstall ? '需要卸除存档格式桥接缝。'
        : result.needsApply ? '需要施加存档格式桥接缝。' : '存档格式桥接缝已是最新。')
    process.exitCode = (result.needsApply || result.needsUninstall) ? 3 : 0
  } catch (error) {
    console.error('存档格式桥接缝失败：' + String(error?.message || error))
    process.exitCode = 1
  }
}
